p='src/main/frontend/src/app/features/people/people.ts'
s=open(p).read()
old=s[s.index("  /** The person's backing: their patrons' due-totals"):s.index("  protected clearPatronError")]
new='''  /** The person's backing: their patrons' settled figures added up, over their SETTLED claims dated
   *  within the 90 days up to and including the sheet's today, each at its frozen figure; 0.00 with none. */
  protected backing(person: PersonView): string {
    const today = this.session.sheet()?.today;
    if (today === undefined) return money(0);
    const from = daysBefore(today, 89);
    const patrons = new Set(person.patronIds);
    let total = 0;
    for (const c of this.claims()) {
      if (patrons.has(c.personId) && c.status === 'SETTLED' && c.settledDue !== null
        && c.date >= from && c.date <= today) total += cents(c.settledDue);
    }
    return money(total);
  }

'''
s=s.replace(old,new)
open(p,'w').write(s)
EOF
grep -n "readonly claims\b\|claims = signal" src/main/frontend/src/app/features/people/people.ts; bin/e2e 2>&1 | tail -15

